}

function createMockStartStages(preflight: StudioNewReviewPreflightResponse | null): StartStageState[] {
  const baseStages: StartStageState[] = [
    {
      stage: 'checkpoint',
      label: 'Checkpoint resolved',
      detail: 'Nimbus locked onto the current commit checkpoint.',
      state: 'completed',
    },
  ];

  if (preflight?.startability === 'intent_aware') {
    baseStages.push({
      stage: 'entire_context',
      label: 'Entire context loaded',
      detail: 'Nimbus found the available Entire context for this review.',
      state: 'completed',
    });
  }

  baseStages.push(
    {
      stage: 'workspace',
      label: 'Workspace prepared',
      detail: 'Nimbus prepared the launch workspace for the review session.',
      state: 'completed',
    },
    {
      stage: 'review_creation',
      label: 'Session creation simulated',
      detail: 'Mock mode stops here so you can inspect the UI without creating a real review.',
      state: 'completed',
    }
  );

  return baseStages;
}

function isTerminalPhase(phase: ReviewSessionResponse['phase']): boolean {
  return phase === 'completed' || phase === 'failed' || phase === 'cancelled';
}

function sessionRoute(session: Pick<ReviewSessionResponse, 'id'>): string {
  return `/sessions/${encodeURIComponent(session.id)}`;
}

function pickCurrentCommitSession(
  sessions: ReviewSessionResponse[],
  commitSha: string | null | undefined
): ReviewSessionResponse | null {
  if (!commitSha) {
    return null;
  }
  return (
    sessions
      .filter((session) => session.anchorCommitSha === commitSha)
      .slice()
      .sort((left, right) => {
        const terminalDelta = Number(isTerminalPhase(left.phase)) - Number(isTerminalPhase(right.phase));
        if (terminalDelta !== 0) {
          return terminalDelta;
        }

        }
        return Date.parse(right.updatedAt) - Date.parse(left.updatedAt);
      })[0] ?? null
  );
}

function resolveLaunchState(input: {
  loading: boolean;
  starting: boolean;
  hasRepoContext: boolean;
  preflight: StudioNewReviewPreflightResponse | null;
  error: string | null;
}): LaunchState {
  if (input.starting) {
    return 'starting';
  }
  if (input.loading && !input.preflight && !input.error) {
    return 'checking';
  }
  if (!input.hasRepoContext) {
    return 'blocked';
  }
  if (input.preflight?.startability === 'intent_aware') {
    return 'ready';
  }
  if (input.preflight?.startability === 'basic') {
    return 'basic';
  }
  if (input.preflight?.startability === 'blocked' || input.error) {
    return 'blocked';
  }
  return 'checking';
}

function launchStateLabel(state: LaunchState): string {
  switch (state) {
    case 'ready':
      return 'Ready';
    case 'basic':
      return 'Basic mode';
    case 'blocked':
      return 'Blocked';
    case 'starting':
      return 'Starting';
    default:
      return 'Checking';
  }
}

function launchSupportCopy(state: LaunchState, input: {
  hasRepoContext: boolean;
  preflight: StudioNewReviewPreflightResponse | null;
  error: string | null;
}): string | null {
  if (state === 'basic') {
    return 'Entire context is unavailable. Nimbus can still review the latest commit in basic mode.';
  }
  if (state === 'starting') {
    return 'Nimbus is resolving the latest commit and opening the session.';
  }
  if (state === 'blocked') {
    if (!input.hasRepoContext) {
      return 'Open Review Studio from inside a git repository.';
    }
    if (!input.preflight?.commitSha) {
      return 'Make a commit to start a review.';
    }
    return (
      input.preflight?.blockingIssues[0]?.message ??
      input.preflight?.error?.message ??
      input.error ??
      'Nimbus could not resolve a reviewable latest commit.'
    );
  }
  return null;
}

function modeLabel(preflight: StudioNewReviewPreflightResponse | null): string {
  if (!preflight) {
    return 'Checking';
  }
  if (preflight.startability === 'intent_aware') {
    return 'Found';
  }
  if (preflight.startability === 'basic') {
    return 'Unavailable';
  }
  return 'Checking';
}

function preflightSignalLabel(state: LaunchState): string {
  switch (state) {
    case 'ready':
      return 'Ready';
    case 'basic':
      return 'Ready';
    case 'blocked':
      return 'Blocked';
    case 'starting':
      return 'Starting';
    default:
      return 'Checking';
  }
}

async function fetchJson(input: string): Promise<unknown> {
  const response = await fetch(input, { cache: 'no-store' });
  if (!response.ok) {
    throw new Error(`Request failed (${response.status})`);
  }
  return response.json();
}

