  }
  return {
    id: `snapshot-${activity.updatedAt}-${activity.state}-${activity.currentReviewStatus ?? 'none'}`,
    kind: 'snapshot',
    createdAt: activity.updatedAt,
    passIndex: activity.passCount > 0 ? Math.max(0, activity.passCount - 1) : null,
    line: activity.detail,
  };
}

