}

.launch-copy {
  display: flex;
  flex-direction: column;
  gap: 0.42rem;
}

.launch-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(1.2rem, 2vw, 1.56rem);
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.launch-panel .panel-body {
