  color: #e3c9b1;
  background: none;
  border: 0;
  border-radius: 0;
  padding: 0;
}

.launch-subline {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
  letter-spacing: 0.02em;
  opacity: 0.92;
}

.launch-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  font-size: 0.94rem;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
  border: 0;
}

.launch-state-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 0.9rem;
}

.launch-primary-button {
  padding: 0.62rem 0.92rem;
  font-size: 0.94rem;
  white-space: nowrap;
}

.launch-status.checking,
.launch-status.starting {
  color: var(--brand);
}

.launch-status.ready {
  color: var(--success);
}

.launch-status.basic {
  color: var(--warning);
}

.launch-status.blocked {
  color: var(--danger);
}

.launch-progress {
  border: 1px solid var(--border);
  background: rgba(24, 24, 24, 0.9);
  border-radius: 6px;
}

.launch-control-panel {
  gap: 0.68rem;
}

.launch-signal-row {
  display: flex;
