  align-items: center;
  gap: 0.52rem;
  padding: 0.52rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(24, 24, 24, 0.94);
}

.launch-signal span {
  color: var(--muted);
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.launch-signal strong {
  font-size: 0.86rem;
  letter-spacing: 0.01em;
}

.launch-signal.ready {
  border-color: rgba(22, 101, 52, 0.18);
}

.launch-signal.basic {
  border-color: rgba(180, 83, 9, 0.2);
}

.launch-signal.blocked {
  border-color: rgba(185, 28, 28, 0.2);
}

.launch-inline-note {
  margin: 0;
  color: #d6b89c;
  font-size: 0.9rem;
  line-height: 1.48;
  padding: 0.5rem 0.55rem;
  border: 1px solid rgba(185, 132, 79, 0.16);
  border-radius: 4px;
  background: rgba(185, 132, 79, 0.05);
}

.session-shell {
  max-width: none;
  width: 100%;
  padding-left: 1.25rem;
  padding-right: 1.25rem;
  gap: 0.85rem;
}

.session-stage-card,
.session-terminal-card {
  border-top: 3px solid rgba(185, 132, 79, 0.58);
}

.session-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(1.24rem, 2vw, 1.62rem);
  line-height: 1.08;
  letter-spacing: -0.03em;
}

.session-stage-header {
  align-items: center;
}

.session-stage-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 0.85rem;
}

.session-live-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(280px, 0.95fr);
  gap: 0.9rem;
  align-items: start;
}

.session-console-section,
.session-findings-section {
  gap: 0.62rem;
}

.session-findings-scroll {
  max-height: 21rem;
  overflow: auto;
  padding-right: 0.12rem;
}

.session-human-step-card {
  gap: 0.72rem;
  border-top: 3px solid rgba(185, 132, 79, 0.58);
}

.session-human-step-list {
  margin: 0;
  padding-left: 1.1rem;
  display: flex;
  flex-direction: column;
  gap: 0.48rem;
  color: var(--text);
}

.session-human-step-list li {
  line-height: 1.48;
}

.session-result-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 0.7rem;
}

.session-result-card {
  padding: 0.82rem 0.9rem;
  border: 1px solid var(--border);
  background: rgba(24, 24, 24, 0.94);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 0.34rem;
}

.session-result-card span {
  color: var(--muted);
  font-size: 0.78rem;
}

.session-result-card strong {
  display: block;
  font-size: 1.05rem;
}

.session-result-card p {
  margin: 0;
  line-height: 1.45;
}

.session-diff-card {
  border: 1px solid var(--border);
  background: rgba(18, 18, 18, 0.96);
}

.session-file-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.session-file-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.32rem;
  padding: 0.28rem 0.52rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(24, 24, 24, 0.94);
  color: var(--text);
  font-size: 0.78rem;
}

.session-finding-list .finding-card {
  padding: 0.78rem 0.82rem;
}

@media (min-width: 860px) {
  .hero-card {
    grid-template-columns: minmax(0, 1.6fr) minmax(260px, 0.95fr);
    align-items: start;
  }

  .hero-meta {
    align-content: start;
  }
}

@media (max-width: 720px) {
  .studio-shell {
    padding-top: 0.75rem;
  }

  .hero-card,
  .panel-card,
  .diff-card {
    padding: 0.85rem;
  }

  .launch-shell {
    padding-top: 0.6rem;
  }

  .session-shell {
    padding-left: 1rem;
    padding-right: 1rem;
  }

  .session-live-grid {
    grid-template-columns: 1fr;
  }

  .session-findings-scroll {
    max-height: none;
    overflow: visible;
    padding-right: 0;
  }

  .hero-title-row,
  .panel-header,
  .section-header,
  .check-card-header,
  .finding-header,
  .timeline-heading,
  .pass-toggle,
  .meta-row,
  .inline-session-card,
  .launch-state-actions,
  .session-stage-actions {
    flex-direction: column;
    align-items: flex-start;
  }

  .launch-signal-row {
    flex-direction: column;
    align-items: flex-start;
  }

  .activity-console-toolbar {
    flex-direction: column;
    align-items: flex-start;
  }

  .activity-console-window {
    min-height: 12rem;
    max-height: 18rem;
  }

  .activity-console-line {
    grid-template-columns: 1fr;
    gap: 0.25rem;
  }

  .timeline-item {
    grid-template-columns: 1fr;
  }
}

