function resolveMockSessionState(sessionId: string | undefined): MockSessionState {
  const routeValue = sessionId?.startsWith('mock-') ? decodeURIComponent(sessionId.slice(5)).trim().toLowerCase() : '';
  const envValue = ((import.meta.env.VITE_STUDIO_MOCK_SESSION_STATE as string | undefined) ?? '').trim().toLowerCase();
  const raw = routeValue || envValue;
  if (
    raw === 'preparing' ||
    raw === 'reviewing' ||
    raw === 'fixing' ||
    raw === 'verifying' ||
    raw === 'waiting' ||
    raw === 'completed_diff' ||
    raw === 'completed_empty' ||
    raw === 'failed'
