  const envValue = (env.VITE_STUDIO_MOCK_SESSION_STATE ?? '').trim().toLowerCase();
  const raw = routeValue || envValue;
  if (
    raw === 'preparing' ||
    raw === 'reviewing' ||
    raw === 'fixing' ||
    raw === 'verifying' ||
    raw === 'waiting' ||
    raw === 'completed_diff' ||
    raw === 'completed_empty' ||
    raw === 'failed'
