                <span>Nimbus is resolving context, creating the review, and routing into the session.</span>
              </div>
              <ol className="timeline-list">
                {props.startStages.map((stage, index) => (
                  <motion.li
                    key={stage.stage}
                    className="timeline-item"
                    initial={reduceMotion ? false : { opacity: 0, y: 6 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={reduceMotion ? undefined : { delay: index * 0.03, duration: 0.16 }}
                  >
                    <span className={`timeline-state ${stage.state}`}>{stage.state === 'completed' ? 'Done' : 'Live'}</span>
                    <div>
                      <strong>{stage.label}</strong>
                      <p>{stage.detail}</p>
                    </div>
                  </motion.li>
                ))}
              </ol>
            </motion.div>
          ) : null}
        </AnimatePresence>

        {props.error && props.preflight ? (
          <div className="notice-card error">
            <strong>Background refresh failed</strong>
            <p>{props.error}</p>
          </div>
        ) : null}
      </motion.section>
    </main>
  );
}

import type { StudioNewReviewPreflightResponse } from '../../types';

export type LaunchState = 'checking' | 'ready' | 'basic' | 'blocked' | 'starting';

export function resolveLaunchState(input: {
  loading: boolean;
  starting: boolean;
  hasRepoContext: boolean;
  preflight: StudioNewReviewPreflightResponse | null;
  error: string | null;
}): LaunchState {
  if (input.starting) {
    return 'starting';
  }
  if (input.loading && !input.preflight && !input.error) {
    return 'checking';
  }
  if (!input.hasRepoContext) {
    return 'blocked';
  }
  if (input.preflight?.startability === 'intent_aware') {
    return 'ready';
  }
  if (input.preflight?.startability === 'basic') {
    return 'basic';
  }
  if (input.preflight?.startability === 'blocked' || input.error) {
    return 'blocked';
  }
  return 'checking';
}

export function launchStateLabel(state: LaunchState): string {
  switch (state) {
    case 'ready':
      return 'Ready';
    case 'basic':
      return 'Basic mode';
    case 'blocked':
      return 'Blocked';
    case 'starting':
      return 'Starting';
    default:
      return 'Checking';
  }
}

export function launchSupportCopy(
  state: LaunchState,
  input: {
    hasRepoContext: boolean;
    preflight: StudioNewReviewPreflightResponse | null;
    error: string | null;
  }
): string | null {
  if (state === 'basic') {
    return 'Entire context is unavailable. Nimbus can still review the latest commit in basic mode.';
  }
  if (state === 'starting') {
    return 'Nimbus is resolving the latest commit and opening the session.';
  }
  if (state === 'blocked') {
    if (!input.hasRepoContext) {
      return 'Open Review Studio from inside a git repository.';
    }
    if (!input.preflight?.commitSha) {
      return 'Make a commit to start a review.';
    }
    return (
      input.preflight?.blockingIssues[0]?.message ??
      input.preflight?.error?.message ??
      input.error ??
      'Nimbus could not resolve a reviewable latest commit.'
    );
  }
  return null;
}

export function modeLabel(preflight: StudioNewReviewPreflightResponse | null): string {
  if (!preflight) {
    return 'Checking';
  }
  if (preflight.startability === 'intent_aware') {
    return 'Found';
  }
  if (preflight.startability === 'basic') {
    return 'Unavailable';
  }
  return 'Checking';
}

export function preflightSignalLabel(state: LaunchState): string {
  switch (state) {
    case 'ready':
    case 'basic':
      return 'Ready';
    case 'blocked':
      return 'Blocked';
    case 'starting':
      return 'Starting';
    default:
      return 'Checking';
  }
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { useStudioDataSource } from '../../data/studio/StudioDataSource';
import type {
  ReviewSessionResponse,
  StudioContextResponse,
  StudioNewReviewPreflightResponse,
  StudioNewReviewStartStageEvent,
} from '../../types';
import { resolveLaunchState } from './launchViewModel';

const LAST_CHECKPOINTS = 1 as const;
const HOME_REFRESH_INTERVAL_MS = 3_000;

export interface StudioLaunchControllerResult {
  context: StudioContextResponse | null;
  preflight: StudioNewReviewPreflightResponse | null;
  currentSession: ReviewSessionResponse | null;
  loading: boolean;
  error: string | null;
  starting: boolean;
  startStages: StudioNewReviewStartStageEvent[];
  startError: string | null;
  launchState: ReturnType<typeof resolveLaunchState>;
  nextRoutePath: string | null;
  handleStart(): void;
}

export function useStudioLaunchController(): StudioLaunchControllerResult {
  const dataSource = useStudioDataSource();
  const startSubscriptionRef = useRef<{ close(): void } | null>(null);
  const hasLoadedRef = useRef(false);
  const [context, setContext] = useState<StudioContextResponse | null>(null);
  const [preflight, setPreflight] = useState<StudioNewReviewPreflightResponse | null>(null);
  const [currentSession, setCurrentSession] = useState<ReviewSessionResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [starting, setStarting] = useState(false);
  const [startStages, setStartStages] = useState<StudioNewReviewStartStageEvent[]>([]);
  const [startError, setStartError] = useState<string | null>(null);
  const [nextRoutePath, setNextRoutePath] = useState<string | null>(null);

  const loadHome = useCallback(
    async (options?: { background?: boolean }) => {
      const background = options?.background === true;
      if (!background) {
        setLoading(true);
        setError(null);
      }
      try {
        const next = await dataSource.loadLaunchState({ lastCheckpoints: LAST_CHECKPOINTS });
        setContext(next.context);
        setPreflight(next.preflight);
        setCurrentSession(next.currentSession);
        setError(null);
        hasLoadedRef.current = true;
      } catch (loadError) {
        if (!background || !hasLoadedRef.current) {
          setError(loadError instanceof Error ? loadError.message : String(loadError));
        }
      } finally {
        if (!background) {
          setLoading(false);
        }
      }
    },
    [dataSource]
  );

  useEffect(() => {
    void loadHome();
    return () => {
      startSubscriptionRef.current?.close();
      startSubscriptionRef.current = null;
    };
  }, [loadHome]);

  useEffect(() => {
    const refresh = (): void => {
      if (starting) {
        return;
      }
      void loadHome({ background: true });
    };
    const interval = window.setInterval(refresh, HOME_REFRESH_INTERVAL_MS);
    const handleFocus = (): void => refresh();
    const handleVisibility = (): void => {
      if (document.visibilityState === 'visible') {
        refresh();
      }
    };
    window.addEventListener('focus', handleFocus);
    document.addEventListener('visibilitychange', handleVisibility);
    return () => {
      window.clearInterval(interval);
      window.removeEventListener('focus', handleFocus);
      document.removeEventListener('visibilitychange', handleVisibility);
    };
  }, [loadHome, starting]);

  const handleStart = useCallback(() => {
    if (!context?.repo || !context.branch) {
      setStartError('Studio could not detect the current repository and branch.');
      return;
    }
    startSubscriptionRef.current?.close();
    setStarting(true);
    setStartError(null);
    setStartStages([]);
    setNextRoutePath(null);

    startSubscriptionRef.current = dataSource.startSession(
      {
        repo: context.repo,
        branch: context.branch,
        lastCheckpoints: LAST_CHECKPOINTS,
        policyMode: 'auto',
      },
      {
        onEvent(event) {
          if (event.type === 'stage') {
            setStartStages((current) => {
              const next = [...current];
              const existingIndex = next.findIndex((entry) => entry.stage === event.stage);
              if (existingIndex >= 0) {
                next.splice(existingIndex, 1, event);
                return next;
              }
              return [...next, event];
            });
            return;
          }
          if (event.type === 'completed') {
            setStarting(false);
            setNextRoutePath(event.routePath);
            startSubscriptionRef.current?.close();
            startSubscriptionRef.current = null;
            return;
          }
          setStarting(false);
          setStartError(event.message);
        },
        onError(startFailure) {
          setStarting(false);
          setStartError(startFailure.message);
        },
      }
    );
  }, [context?.branch, context?.repo, dataSource]);

  const hasRepoContext = Boolean(context?.repo && context?.branch);
  const launchState = resolveLaunchState({
    loading,
    starting,
    hasRepoContext,
    preflight,
    error,
  });

  return {
    context,
    preflight,
    currentSession,
    loading,
    error,
    starting,
    startStages,
    startError,
    launchState,
    nextRoutePath,
    handleStart,
  };
}

