                    </article>
                  ))}
                </div>
              )}
            </div>
          </motion.section>
        </div>
      ) : (
        <>
          {viewModel.result ? (
            <motion.section className="flow-section" {...motionProps}>
              <div className="section-header">
                <div>
                  <p className="eyebrow">Outcome</p>
