  --radius-md: 14px;
  --radius-sm: 10px;
  --font-display: "Lexend", "Avenir Next", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --font-body: "Source Sans 3", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --font-code: "JetBrains Mono", "SFMono-Regular", "SF Mono", Consolas, "Liberation Mono", Menlo, monospace;
  --action: #b9844f;
  --action-strong: #94643c;
  --accent-soft: rgba(185, 132, 79, 0.11);
  --accent-strong: #7b5030;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  min-height: 100%;
}

body {
  margin: 0;
  font-family: var(--font-body);
  color: var(--text);
  background:
    radial-gradient(circle at top left, rgba(185, 132, 79, 0.1), transparent 28%),
    radial-gradient(circle at top right, rgba(152, 109, 72, 0.06), transparent 22%),
    linear-gradient(180deg, var(--bg) 0%, var(--bg-accent) 100%);
}

a {
  color: inherit;
}

button,
textarea {
  font: inherit;
}

button {
  border: 0;
  background: none;
}

textarea {
  width: 100%;
  min-height: 5rem;
  resize: vertical;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0.9rem 1rem;
  color: var(--text);
  background: rgba(28, 28, 28, 0.92);
}

textarea:focus {
  outline: 2px solid rgba(249, 115, 22, 0.24);
  border-color: var(--action);
}

code,
pre {
  font-family: var(--font-code);
}

pre {
  margin: 0;
  white-space: pre-wrap;
  overflow-x: auto;
}

.studio-shell {
  max-width: 1160px;
  margin: 0 auto;
  padding: 1rem 1rem 2rem;
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
}

.hero-card,
.panel-card,
.notice-card,
.empty-card,
.pass-card,
.summary-card,
.check-card,
.diff-card,
.finding-card {
  border: 1px solid var(--border);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.hero-card,
.panel-card,
.diff-card {
  border-radius: var(--radius-lg);
}

.notice-card,
.empty-card,
.pass-card,
.summary-card,
.check-card,
.finding-card {
  border-radius: var(--radius-md);
}

.hero-card {
  padding: 1rem 1.1rem;
  display: grid;
  gap: 0.8rem;
  background:
    linear-gradient(140deg, rgba(24, 24, 24, 0.98), rgba(16, 16, 16, 0.98)),
    linear-gradient(180deg, rgba(249, 115, 22, 0.07), transparent);
}

.hero-copy {
  display: flex;
  flex-direction: column;
  gap: 0.38rem;
}

.hero-title-row {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: flex-start;
}

.hero-card h1,
.panel-card h2,
.flow-section h2 {
  margin: 0;
  font-family: var(--font-display);
  line-height: 1.12;
  letter-spacing: -0.04em;
}

.hero-card h1 {
  font-size: clamp(1.35rem, 3vw, 2.05rem);
}

.panel-card h2,
.flow-section h2 {
  font-size: clamp(1rem, 2vw, 1.35rem);
}

.hero-body,
.panel-body,
.panel-subtle,
.finding-card p,
.summary-card p,
.timeline-item p,
.check-card p,
.notice-card p,
.empty-card,
.field-stack span,
.meta-row span,
.meta-chip span {
  margin: 0;
}

.hero-body {
  font-size: 0.93rem;
  line-height: 1.45;
  max-width: 46rem;
}

.panel-body {
  line-height: 1.45;
  font-size: 0.93rem;
}

.panel-subtle {
  font-size: 0.88rem;
  line-height: 1.42;
}

.panel-subtle,
.meta-chip span,
.meta-row span,
.timeline-heading span,
.finding-note span,
.field-stack span,
.finding-location,
.eyebrow {
  color: var(--muted);
}

.eyebrow {
  margin: 0 0 0.18rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.64rem;
  font-weight: 700;
}

.hero-meta,
.summary-grid,
.check-grid,
.studio-grid {
  display: grid;
  gap: 0.65rem;
}

.studio-grid,
.summary-grid,
.check-grid {
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.meta-chip,
.summary-card,
.check-card {
  padding: 0.72rem 0.82rem;
  background: rgba(248, 250, 252, 0.92);
}

.meta-chip strong,
.summary-card strong,
.meta-row strong {
  display: block;
  margin-top: 0.22rem;
}

.status-pill,
.severity-pill,
.timeline-state {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  padding: 0.24rem 0.55rem;
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.status-pill.live {
  background: var(--brand-soft);
  color: var(--brand);
}

.status-pill.waiting {
  background: var(--warning-soft);
  color: var(--warning);
}

.status-pill.terminal,
.status-pill.muted {
  background: rgba(247, 243, 238, 0.08);
  color: var(--text);
}

.severity-pill.danger {
  background: var(--danger-soft);
  color: var(--danger);
}

.severity-pill.warning {
  background: var(--warning-soft);
  color: var(--warning);
}

.severity-pill.neutral {
  background: rgba(31, 26, 20, 0.08);
  color: var(--text);
}

.timeline-state.active,
.timeline-state.live {
  background: var(--brand-soft);
  color: var(--brand-strong);
}

.timeline-state.completed {
  background: var(--success-soft);
  color: var(--success);
}

.timeline-state.warning {
  background: var(--warning-soft);
  color: var(--warning);
}

.panel-card,
.flow-section {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.panel-card {
  padding: 0.95rem;
}

.panel-header,
.section-header,
.check-card-header,
.finding-header,
.timeline-heading {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: flex-start;
}

.button-row,
.hero-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
}

.primary-button,
.secondary-button,
.pass-toggle {
  border-radius: 999px;
  cursor: pointer;
}

.primary-button,
.secondary-button {
  padding: 0.62rem 0.9rem;
  font-weight: 700;
  font-size: 0.88rem;
}

.primary-button {
  background: linear-gradient(180deg, var(--action), var(--action-strong));
  color: #fff1e6;
}

.secondary-button {
  background: rgba(247, 243, 238, 0.06);
  color: var(--text);
  border: 1px solid var(--border);
}

.primary-button:disabled,
.secondary-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.inline-link {
  text-decoration: none;
  border-bottom: 1px solid currentColor;
  padding-bottom: 0.05rem;
}

.notice-card,
.empty-card {
  padding: 0.8rem 0.9rem;
  line-height: 1.45;
}

.notice-card strong {
  display: block;
  margin-bottom: 0.22rem;
}

.notice-card.warning {
  border-color: rgba(185, 132, 79, 0.26);
  background: rgba(56, 42, 30, 0.82);
  color: #ecd9c4;
}

.notice-card.error {
  border-color: rgba(161, 74, 74, 0.28);
  background: rgba(62, 29, 29, 0.84);
  color: #f0d7d7;
}

.notice-card.success {
  border-color: rgba(69, 128, 97, 0.28);
  background: rgba(27, 50, 39, 0.84);
  color: #dff0e5;
}

.timeline-card,
.diff-card {
  padding: 0.8rem 0.9rem;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}

.activity-console-card {
  border: 1px solid rgba(20, 16, 12, 0.55);
  border-radius: var(--radius-lg);
  background: linear-gradient(180deg, rgba(24, 19, 14, 0.98), rgba(16, 13, 10, 0.98));
  box-shadow: var(--shadow);
  color: #f7eddf;
  overflow: hidden;
}

.activity-console-toolbar {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: flex-start;
  padding: 0.78rem 0.9rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.03);
}

.activity-console-toolbar strong {
  display: block;
  margin-bottom: 0.18rem;
}

.activity-console-toolbar .panel-subtle {
  color: rgba(232, 218, 197, 0.72);
}

.activity-console-toolbar-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  align-items: center;
  color: rgba(232, 218, 197, 0.72);
  font-size: 0.78rem;
  white-space: nowrap;
}

.activity-console-window {
  max-height: 21rem;
  min-height: 14rem;
  overflow: auto;
  padding: 0.5rem 0.65rem 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  scroll-behavior: smooth;
}

.activity-console-line {
  display: grid;
  grid-template-columns: minmax(10rem, auto) minmax(0, 1fr);
  gap: 0.8rem;
  align-items: flex-start;
  padding: 0.34rem 0.2rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  font-family: "SFMono-Regular", "SF Mono", Consolas, "Liberation Mono", Menlo, monospace;
  font-size: 0.82rem;
  line-height: 1.45;
}

.activity-console-line:last-child {
  border-bottom: 0;
}

.activity-console-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.38rem;
  align-items: center;
  color: rgba(232, 218, 197, 0.62);
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.activity-console-tag {
  display: inline-flex;
  align-items: center;
  padding: 0.08rem 0.36rem;
  border: 1px solid rgba(202, 138, 4, 0.38);
  background: rgba(202, 138, 4, 0.14);
  color: rgba(245, 222, 185, 0.92);
  font-size: 0.66rem;
  letter-spacing: 0.08em;
}

.activity-console-body {
  min-width: 0;
  color: #f7eddf;
  word-break: break-word;
}

.activity-console-line.checkpoint {
  padding: 0.42rem 0.35rem;
  border-left: 2px solid rgba(202, 138, 4, 0.72);
  background:
    linear-gradient(90deg, rgba(202, 138, 4, 0.18), rgba(202, 138, 4, 0.06) 38%, rgba(202, 138, 4, 0.01));
  box-shadow: inset 0 0 0 1px rgba(202, 138, 4, 0.1);
  animation: checkpoint-flash 1.1s ease-out 1;
}

.activity-console-line.checkpoint .activity-console-meta {
  color: rgba(245, 222, 185, 0.82);
}

.activity-console-line.checkpoint .activity-console-body {
  color: #fff3dc;
}

.activity-console-line.finding .activity-console-body {
  color: #ffdbab;
}

.activity-console-line.remediation .activity-console-body {
  color: #d6f6e2;
}

.activity-console-line.terminal .activity-console-body,
.activity-console-line.snapshot .activity-console-body {
  color: #fff8ef;
}

.activity-console-line.policy .activity-console-body {
  color: #d5e6ff;
}

@keyframes checkpoint-flash {
  0% {
    box-shadow:
      inset 0 0 0 1px rgba(202, 138, 4, 0.28),
      0 0 0 0 rgba(202, 138, 4, 0.28);
    background:
      linear-gradient(90deg, rgba(202, 138, 4, 0.28), rgba(202, 138, 4, 0.1) 40%, rgba(202, 138, 4, 0.02));
  }
  100% {
    box-shadow: inset 0 0 0 1px rgba(202, 138, 4, 0.1);
    background:
      linear-gradient(90deg, rgba(202, 138, 4, 0.18), rgba(202, 138, 4, 0.06) 38%, rgba(202, 138, 4, 0.01));
  }
}

@media (prefers-reduced-motion: reduce) {
  .activity-console-line.checkpoint {
    animation: none;
  }
}

.timeline-list,
.finding-list,
.pass-stack,
.meta-stack {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.timeline-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.timeline-item {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.7rem;
  padding: 0.65rem 0;
  border-top: 1px solid rgba(31, 26, 20, 0.08);
}

.timeline-item:first-child {
  border-top: 0;
  padding-top: 0;
}

.finding-list {
  gap: 0.62rem;
}

.finding-card {
  padding: 0.85rem 0.9rem;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.finding-header {
  align-items: center;
}

.finding-note {
  display: flex;
  flex-direction: column;
  gap: 0.22rem;
}

.flow-section {
  gap: 0.7rem;
}

.pass-card {
  overflow: hidden;
}

.pass-toggle {
  width: 100%;
  padding: 0.8rem 0.9rem;
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: flex-start;
  text-align: left;
  border-radius: 0;
  background: transparent;
}

.pass-toggle p {
  margin: 0.2rem 0 0;
  line-height: 1.42;
}

.pass-body {
  padding: 0 0.9rem 0.8rem;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}

.meta-row {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
}

.inline-findings {
  display: flex;
  flex-direction: column;
  gap: 0.38rem;
}

.pass-stream-note {
  padding: 0.72rem 0.82rem;
  border: 1px solid rgba(249, 115, 22, 0.12);
  border-radius: var(--radius-sm);
  background: rgba(24, 24, 24, 0.86);
  color: var(--muted);
  font-size: 0.86rem;
  line-height: 1.45;
}

.inline-findings ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.32rem;
}

.inline-findings li {
  display: flex;
  gap: 0.6rem;
  align-items: center;
}

.diff-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.52rem;
  color: var(--muted);
  font-size: 0.84rem;
}

.diff-card pre,
.notice-card pre {
  padding: 0.75rem;
  border-radius: var(--radius-sm);
  background: #0f172a;
  color: #eff6ff;
  max-height: 18rem;
  overflow: auto;
}

.policy-grid {
  display: grid;
  gap: 0.7rem;
}

.field-stack {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.inline-session-card {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  align-items: center;
  padding: 0.72rem 0.82rem;
  border: 1px solid rgba(249, 115, 22, 0.12);
  border-radius: var(--radius-sm);
  background: rgba(24, 24, 24, 0.86);
}

.inline-session-card strong {
  display: block;
}

.inline-session-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  align-items: center;
  color: var(--muted);
  font-size: 0.82rem;
}

.launch-shell {
  max-width: 700px;
  padding-top: 0.85rem;
  gap: 0.6rem;
}

.launch-panel {
  gap: 0.72rem;
  padding: 0.92rem 0.96rem;
  border-radius: 6px;
}

.launch-copy {
  display: flex;
  flex-direction: column;
  gap: 0.42rem;
}

.launch-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(1.2rem, 2vw, 1.56rem);
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.launch-panel .panel-body {
  font-size: 0.96rem;
  line-height: 1.52;
  color: #e3c9b1;
  background: none;
  border: 0;
  border-radius: 0;
  padding: 0;
}

.launch-subline {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
  letter-spacing: 0.02em;
  opacity: 0.92;
}

.launch-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  font-size: 0.94rem;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
  border: 0;
}

.launch-state-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 0.9rem;
}

.launch-primary-button {
  padding: 0.62rem 0.92rem;
  font-size: 0.94rem;
  white-space: nowrap;
}

.launch-status.checking,
.launch-status.starting {
  color: var(--brand);
}

.launch-status.ready {
  color: var(--success);
}

.launch-status.basic {
  color: var(--warning);
}

.launch-status.blocked {
  color: var(--danger);
}

.launch-progress {
  border: 1px solid var(--border);
  background: rgba(24, 24, 24, 0.9);
  border-radius: 6px;
}

.launch-control-panel {
  gap: 0.68rem;
}

.launch-signal-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
}

.launch-signal {
  display: inline-flex;
  align-items: center;
  gap: 0.52rem;
  padding: 0.52rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(24, 24, 24, 0.94);
}

.launch-signal span {
  color: var(--muted);
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.launch-signal strong {
  font-size: 0.86rem;
  letter-spacing: 0.01em;
}

.launch-signal.ready {
  border-color: rgba(22, 101, 52, 0.18);
}

.launch-signal.basic {
  border-color: rgba(180, 83, 9, 0.2);
}

.launch-signal.blocked {
  border-color: rgba(185, 28, 28, 0.2);
}

.launch-inline-note {
  margin: 0;
  color: #d6b89c;
  font-size: 0.9rem;
  line-height: 1.48;
  padding: 0.5rem 0.55rem;
  border: 1px solid rgba(185, 132, 79, 0.16);
  border-radius: 4px;
  background: rgba(185, 132, 79, 0.05);
}

.session-shell {
  max-width: none;
  width: 100%;
  padding-left: 1.25rem;
  padding-right: 1.25rem;
  gap: 0.85rem;
}

.session-stage-card,
.session-terminal-card {
  border-top: 3px solid rgba(185, 132, 79, 0.58);
}

.session-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(1.24rem, 2vw, 1.62rem);
  line-height: 1.08;
  letter-spacing: -0.03em;
}

.session-stage-header {
  align-items: center;
}

.session-stage-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 0.85rem;
}

.session-live-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(280px, 0.95fr);
  gap: 0.9rem;
  align-items: start;
}

.session-console-section,
.session-findings-section {
  gap: 0.62rem;
}

.session-findings-scroll {
  max-height: 21rem;
  overflow: auto;
  padding-right: 0.12rem;
}

.session-human-step-card {
  gap: 0.72rem;
  border-top: 3px solid rgba(185, 132, 79, 0.58);
}

.session-human-step-list {
  margin: 0;
  padding-left: 1.1rem;
  display: flex;
  flex-direction: column;
  gap: 0.48rem;
  color: var(--text);
}

.session-human-step-list li {
  line-height: 1.48;
}

.session-result-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 0.7rem;
}

.session-result-card {
  padding: 0.82rem 0.9rem;
  border: 1px solid var(--border);
  background: rgba(24, 24, 24, 0.94);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 0.34rem;
}

.session-result-card span {
  color: var(--muted);
  font-size: 0.78rem;
}

.session-result-card strong {
  display: block;
  font-size: 1.05rem;
}

.session-result-card p {
  margin: 0;
  line-height: 1.45;
}

.session-diff-card {
  border: 1px solid var(--border);
  background: rgba(18, 18, 18, 0.96);
}

.session-file-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.session-file-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.32rem;
  padding: 0.28rem 0.52rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(24, 24, 24, 0.94);
  color: var(--text);
  font-size: 0.78rem;
}

.session-finding-list .finding-card {
  padding: 0.78rem 0.82rem;
}

@media (min-width: 860px) {
  .hero-card {
    grid-template-columns: minmax(0, 1.6fr) minmax(260px, 0.95fr);
    align-items: start;
  }

  .hero-meta {
    align-content: start;
  }
}

@media (max-width: 720px) {
  .studio-shell {
    padding-top: 0.75rem;
  }

  .hero-card,
  .panel-card,
  .diff-card {
    padding: 0.85rem;
  }

  .launch-shell {
    padding-top: 0.6rem;
  }

  .session-shell {
    padding-left: 1rem;
    padding-right: 1rem;
  }

  .session-live-grid {
    grid-template-columns: 1fr;
  }

  .session-findings-scroll {
