  border: 1px solid rgba(185, 132, 79, 0.16);
  border-radius: 4px;
  background: rgba(185, 132, 79, 0.05);
}

.launch-progress {
  border: 1px solid var(--border);
  background: rgba(24, 24, 24, 0.9);
  border-radius: 6px;
}

@media (max-width: 860px) {
  .launch-shell {
    padding-top: 0.6rem;
  }

  .launch-state-actions,
  .launch-signal-row {
    flex-direction: column;
    align-items: flex-start;
  }
}

@import './styles/base.css';
@import './styles/studio-launch.css';
@import './styles/studio-session.css';

.session-shell {
  max-width: none;
  width: 100%;
  padding-left: 1.25rem;
  padding-right: 1.25rem;
  gap: 0.85rem;
}

.session-stage-card,
.session-human-step-card {
  border-top: 3px solid rgba(185, 132, 79, 0.58);
}

.session-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(1.24rem, 2vw, 1.62rem);
  line-height: 1.08;
  letter-spacing: -0.03em;
}

.session-stage-header {
  align-items: center;
}

.session-stage-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 0.85rem;
}

.session-live-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(280px, 0.95fr);
  gap: 0.9rem;
  align-items: start;
}

.session-console-section,
.session-findings-section {
  gap: 0.62rem;
}

.session-findings-scroll {
  max-height: 21rem;
  overflow: auto;
  padding-right: 0.12rem;
}

.session-human-step-card {
  display: grid;
  gap: 0.72rem;
}

.session-diff-card {
