import { AnimatePresence, motion, useReducedMotion } from 'framer-motion';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import {
  parseLocalReviewEnvironmentDiffResponse,
  parseLocalReviewEnvironmentMergeBackResponse,
  parseStudioSessionActivityEvent,
  parseStudioSessionAggregateResponse,
} from '../lib/review';
import type {
  LocalReviewEnvironmentDiffResponse,
  LocalReviewEnvironmentMergeBackResponse,
  ReviewContextMode,
  ReviewFinding,
  ReviewPolicyDraft,
  ReviewSessionResponse,
  StudioSessionActivityEntry,
  StudioSessionActivitySnapshot,
  StudioSessionAggregateResponse,
} from '../types';

const API_BASE = (import.meta.env.VITE_NIMBUS_API_BASE_URL as string | undefined)?.replace(/\/$/, '') ?? '';
const STUDIO_MOCK_ENABLED = ['1', 'true', 'yes', 'on'].includes(
  ((import.meta.env.VITE_STUDIO_MOCK as string | undefined) ?? '').trim().toLowerCase()
);
const ENTIRE_DOCS_URL = 'https://github.com/dayhaysoos/nimbus/blob/main/docs/entire/recovery.md';
const REVIEWED_DIFF_MAX_BYTES = 200_000;
const MOCK_REPO = 'dayhaysoos/nimbus';
const MOCK_BRANCH = 'codex/studio-launch-rebuild';

type MockSessionState =
  | 'preparing'
  | 'reviewing'
  | 'fixing'
  | 'verifying'
  | 'waiting'
  | 'completed_diff'
  | 'completed_empty'
  | 'failed';

interface EditablePolicyDraft {
  goal: string;
  prohibitions: string;
  constraints: string;
}

interface AdoptResponse {
  sessionId: string;
  mode: 'worktree' | 'branch';
  branchName: string;
  worktreePath: string | null;
  artifactId: string;
  artifactSha256: string;
  latestReviewId: string;
  anchorCommitSha: string;
  commitSha: string | null;
  enterCommand: string;
}

interface StreamedFinding {
  id: string;
  passIndex: number;
  reviewId: string;
  severity: string;
  title: string;
  description: string;
  location: string | null;
}

interface ActivityConsoleEntry {
  id: string;
  kind: StudioSessionActivityEntry['kind'] | 'snapshot';
  createdAt: string | null;
  passIndex: number | null;
  line: string;
}

interface MockSessionModel {
  id: string;
  state: MockSessionState;
  phase: ReviewSessionResponse['phase'];
  phaseLabel: string;
  tone: 'starting' | 'ready' | 'basic' | 'blocked';
  contextMode: ReviewContextMode;
  summary: string;
  modeSummary: string | null;
  consoleSummary: string;
  findingsSummary: string;
  passCount: number;
  canStream: boolean;
  activity: StudioSessionActivitySnapshot;
  events: StudioSessionActivityEntry[];
  findings: ReviewFinding[];
  note:
    | {
        tone: 'warning' | 'error' | 'success';
        title: string;
        detail: string;
      }
    | null;
  result:
    | {
        outcomeLabel: string;
        recommendation: string;
        changedFiles: number;
        summary: string;
        reviewedDiff:
          | {
              summary: string[];
              patch: string;
              adoptDetail: string;
              branchName: string;
              worktreePath: string;
              enterCommand: string;
              localDiff: string;
              mergeTarget: string;
              sourceBranch: string;
            }
          | null;
        noAdopt:
          | {
              title: string;
              detail: string;
              tone: 'warning' | 'error';
            }
          | null;
      }
    | null;
  humanStep:
    | {
        title: string;
        detail: string;
        checklist: string[];
        safeguard: string;
      }
    | null;
  terminal:
    | {
        title: string;
        detail: string;
      }
    | null;
}

function createEditablePolicyDraft(policy: ReviewPolicyDraft | undefined): EditablePolicyDraft {
  return {
    goal: policy?.goal ?? '',
    prohibitions: (policy?.prohibitions ?? []).join('\n'),
    constraints: (policy?.constraints ?? []).join('\n'),
  };
}

function normalizeEditablePolicyDraft(policy: EditablePolicyDraft): ReviewPolicyDraft {
  const normalizeLines = (input: string): string[] =>
    Array.from(
      new Set(
        input
          .split('\n')
          .map((line) => line.trim())
          .filter(Boolean)
      )
    );

  const goal = policy.goal.trim();
  return {
    goal: goal ? goal : null,
    prohibitions: normalizeLines(policy.prohibitions),
    constraints: normalizeLines(policy.constraints),
  };
}

function readErrorMessage(payload: unknown): string {
  if (typeof payload === 'string' && payload.trim()) {
    return payload.trim();
  }
  if (payload && typeof payload === 'object' && !Array.isArray(payload) && 'error' in payload) {
    const error = (payload as { error?: unknown }).error;
    if (typeof error === 'string' && error.trim()) {
      return error;
    }
    if (error && typeof error === 'object' && !Array.isArray(error) && 'message' in error) {
      const message = (error as { message?: unknown }).message;
      if (typeof message === 'string' && message.trim()) {
        return message;
      }
    }
  }
  return 'Request failed.';
}

async function readJson(response: Response): Promise<unknown> {
  const text = await response.text();
  if (!text.trim()) {
    return {};
  }
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return text;
  }
}

async function fetchAggregate(sessionId: string): Promise<StudioSessionAggregateResponse> {
  const response = await fetch(
    `${API_BASE}/api/studio/sessions/${encodeURIComponent(sessionId)}?includeReviewedDiff=1&includePatch=1&maxBytes=${REVIEWED_DIFF_MAX_BYTES}`
  );
  const payload = await readJson(response);
  if (!response.ok) {
    throw new Error(readErrorMessage(payload));
  }
  return parseStudioSessionAggregateResponse(payload);
}

function resolveContextMode(aggregate: StudioSessionAggregateResponse | null): ReviewContextMode | null {
  if (!aggregate) {
    return null;
  }
  return (
    aggregate.session.outcome?.reviewed.contextMode ??
    aggregate.latestReview?.provenance.reviewContextMode ??
    aggregate.activeReview?.provenance.reviewContextMode ??
    null
  );
}

function isTerminalPhase(phase: ReviewSessionResponse['phase']): boolean {
  return phase === 'completed' || phase === 'failed' || phase === 'cancelled';
}

function modeLabel(mode: ReviewContextMode | null): string {
  if (mode === 'intent_aware') {
    return 'Intent-aware';
  }
  if (mode === 'basic') {
    return 'Basic';
  }
  return 'Pending';
}

function severityClass(severity: string): string {
  if (severity === 'critical' || severity === 'high') {
    return 'severity-pill danger';
  }
  if (severity === 'medium') {
    return 'severity-pill warning';
  }
  if (severity === 'low' || severity === 'info') {
    return 'severity-pill neutral';
  }
  return 'severity-pill neutral';
}

function findingHeading(finding: ReviewFinding): string {
  return finding.title?.trim() || finding.description;
}

function shouldShowFindingDescription(finding: ReviewFinding): boolean {
  const heading = findingHeading(finding).trim();
  const description = finding.description.trim();
  return Boolean(description) && description !== heading;
}

function findingLocation(finding: ReviewFinding): string | null {
  const first = finding.locations[0];
  if (!first) {
    return null;
  }
  if (first.startLine !== null) {
    return `${first.filePath}:${first.startLine}`;
  }
  return first.filePath;
}

function buildStreamedFinding(event: StudioSessionActivityEntry, index: number): StreamedFinding | null {
  if (event.kind !== 'finding') {
    return null;
  }
  const payload = event.payload;
  const title =
    typeof payload.title === 'string' && payload.title.trim()
      ? payload.title.trim()
      : typeof payload.description === 'string' && payload.description.trim()
        ? payload.description.trim()
        : event.detail;
  const locations = Array.isArray(payload.locations) ? payload.locations : [];
  const firstLocation = locations[0];
  let location: string | null = null;
  if (firstLocation && typeof firstLocation === 'object' && !Array.isArray(firstLocation)) {
    const record = firstLocation as { path?: unknown; line?: unknown };
    if (typeof record.path === 'string' && record.path.trim()) {
      location =
        typeof record.line === 'number' && Number.isFinite(record.line) ? `${record.path}:${record.line}` : record.path;
    }
  }

  return {
    id: `${event.reviewId}-${event.seq ?? index}-${index}`,
    passIndex: event.passIndex,
    reviewId: event.reviewId,
    severity: typeof payload.severity === 'string' ? payload.severity : 'info',
    title,
    description: typeof payload.description === 'string' && payload.description.trim() ? payload.description : event.detail,
    location,
  };
}

function formatActivityConsoleTime(value: string | null): string {
  if (!value) {
    return '--:--:--';
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return value;
  }
  return date.toLocaleTimeString([], {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });
}

function activityConsoleKindLabel(kind: ActivityConsoleEntry['kind']): string {
  if (kind === 'snapshot') {
    return 'snapshot';
  }
  return kind.replace(/_/g, ' ');
}

function buildActivityConsoleEntry(event: StudioSessionActivityEntry, index: number): ActivityConsoleEntry {
  const finding = buildStreamedFinding(event, index);
  const line = finding
    ? `${finding.title}${finding.location ? ` (${finding.location})` : ''}${finding.description !== finding.title ? ` — ${finding.description}` : ''}`
    : event.detail.trim() === event.label.trim()
      ? event.detail
      : `${event.label}: ${event.detail}`;
  return {
    id: `${event.reviewId}-${event.seq ?? index}-${event.rawType}-${index}`,
    kind: event.kind,
    createdAt: event.createdAt,
    passIndex: event.passIndex,
    line,
  };
}

function buildActivitySnapshotEntry(activity: StudioSessionActivitySnapshot | null): ActivityConsoleEntry {
  if (!activity) {
    return {
      id: 'snapshot-empty',
      kind: 'snapshot',
      createdAt: null,
      passIndex: null,
      line: 'Waiting for session activity.',
    };
  }
  return {
    id: `snapshot-${activity.updatedAt}-${activity.state}-${activity.currentReviewStatus ?? 'none'}`,
    kind: 'snapshot',
    createdAt: activity.updatedAt,
    passIndex: activity.passCount > 0 ? Math.max(0, activity.passCount - 1) : null,
    line: activity.detail,
  };
}

function findCheckpointConsoleEntryId(entries: ActivityConsoleEntry[], enabled: boolean): string | null {
  if (!enabled) {
    return null;
  }
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    if (entries[index]?.kind === 'policy') {
      return entries[index]?.id ?? null;
    }
  }
  return null;
}

function sessionPhaseLabel(phase: ReviewSessionResponse['phase']): string {
  return phase.replace(/_/g, ' ');
}

function sessionStageTitle(input: {
  phase: ReviewSessionResponse['phase'];
  terminal: boolean;
  waiting: boolean;
}): string {
  if (input.phase === 'failed') {
    return 'Review failed';
  }
  if (input.phase === 'cancelled') {
    return 'Review cancelled';
  }
  if (input.waiting) {
    return 'Review paused';
  }
  if (input.terminal) {
    return 'Review complete';
  }
  return 'Review in progress';
}

function sessionTone(input: {
  phase: ReviewSessionResponse['phase'];
  terminal: boolean;
  waiting: boolean;
}): 'starting' | 'ready' | 'basic' | 'blocked' {
  if (input.phase === 'failed' || input.phase === 'cancelled') {
    return 'blocked';
  }
  if (input.waiting) {
    return 'basic';
  }
  if (input.phase === 'preparing') {
    return 'starting';
  }
  return 'ready';
}

function recommendationLabel(aggregate: StudioSessionAggregateResponse, canShowReviewedDiff: boolean): string {
  if (aggregate.capabilities.canAdopt && aggregate.adopt.available && canShowReviewedDiff) {
    return 'Adopt locally';
  }
  return aggregate.session.outcome?.recommendation?.replace(/_/g, ' ') ?? 'Manual follow-up';
}

function resolveMockSessionState(sessionId: string | undefined): MockSessionState {
  const routeValue = sessionId?.startsWith('mock-') ? decodeURIComponent(sessionId.slice(5)).trim().toLowerCase() : '';
  const envValue = ((import.meta.env.VITE_STUDIO_MOCK_SESSION_STATE as string | undefined) ?? '').trim().toLowerCase();
  const raw = routeValue || envValue;
  if (
    raw === 'preparing' ||
    raw === 'reviewing' ||
    raw === 'fixing' ||
    raw === 'verifying' ||
    raw === 'waiting' ||
    raw === 'completed_diff' ||
    raw === 'completed_empty' ||
    raw === 'failed'
  ) {
    return raw;
  }
  return 'reviewing';
}

function createMockFinding(input: {
  severity: ReviewFinding['severity'];
  title: string;
  description: string;
  filePath: string;
  line: number;
  suggestedFix: string;
}): ReviewFinding {
  return {
    severity: input.severity,
    category: 'logic',
    passType: 'single',
    title: input.title,
    description: input.description,
    locations: [
      {
        filePath: input.filePath,
        startLine: input.line,
        endLine: input.line,
      },
    ],
    suggestedFix: input.suggestedFix,
  };
}

function createMockActivityEvent(input: {
  sessionId: string;
  reviewId: string;
  passIndex: number;
  seq: number;
  createdAt: string;
  kind: StudioSessionActivityEntry['kind'];
  label: string;
  detail: string;
  payload?: Record<string, unknown>;
}): StudioSessionActivityEntry {
  return {
    type: 'activity',
    sessionId: input.sessionId,
    reviewId: input.reviewId,
    passIndex: input.passIndex,
    rawType: input.kind,
    kind: input.kind,
    label: input.label,
    detail: input.detail,
    createdAt: input.createdAt,
    seq: input.seq,
    payload: input.payload ?? {},
  };
}

