function MockReviewSessionPage(props: { sessionId?: string }): JSX.Element {
  const reduceMotion = useReducedMotion();
  const activityConsoleRef = useRef<HTMLDivElement | null>(null);
  const baseMockState = useMemo(() => resolveMockSessionState(props.sessionId), [props.sessionId]);
  const [mockStateOverride, setMockStateOverride] = useState<MockSessionState | null>(null);
  const [mockNotice, setMockNotice] = useState<MockSessionModel['note']>(null);
  const [mockAdopted, setMockAdopted] = useState(false);
  const [mockMergedBack, setMockMergedBack] = useState(false);
  const effectiveMockState = mockStateOverride ?? baseMockState;
  const model = useMemo(() => createMockSessionModel(props.sessionId, effectiveMockState), [props.sessionId, effectiveMockState]);
  const shouldReplayWaiting = effectiveMockState === 'waiting';
  const [visibleCount, setVisibleCount] = useState(model.canStream || shouldReplayWaiting ? Math.min(1, model.events.length) : model.events.length);

  useEffect(() => {
    setMockStateOverride(null);
    setMockNotice(null);
    setMockAdopted(false);
    setMockMergedBack(false);
  }, [baseMockState, props.sessionId]);

  useEffect(() => {
    if (!model.canStream && !shouldReplayWaiting) {
      setVisibleCount(model.events.length);
      return;
    }
    setVisibleCount(Math.min(1, model.events.length));
    const timer = window.setInterval(() => {
      setVisibleCount((current) => {
        if (current >= model.events.length) {
          window.clearInterval(timer);
          return current;
        }
        return current + 1;
      });
    }, 650);
    return () => window.clearInterval(timer);
  }, [model, shouldReplayWaiting]);

  const isWaitingReplayActive = shouldReplayWaiting && visibleCount < model.events.length;
  const visibleEvents = model.canStream || shouldReplayWaiting ? model.events.slice(0, visibleCount) : model.events;
  const visibleFindingCount = visibleEvents.filter((event) => event.kind === 'finding').length;
  const visibleFindings = model.canStream || shouldReplayWaiting ? model.findings.slice(0, visibleFindingCount) : model.findings;
  const activityConsoleEntries = useMemo(() => {
    const entries = visibleEvents.map((event, index) => buildActivityConsoleEntry(event, index));
    if (entries.length === 0) {
      return [buildActivitySnapshotEntry(model.activity)];
    }
    if (!model.canStream && !shouldReplayWaiting) {
      return [...entries, buildActivitySnapshotEntry(model.activity)];
    }
    if (shouldReplayWaiting && !isWaitingReplayActive) {
      return [...entries, buildActivitySnapshotEntry(model.activity)];
    }
    return entries;
  }, [isWaitingReplayActive, model.activity, model.canStream, shouldReplayWaiting, visibleEvents]);

  useEffect(() => {
    const consoleNode = activityConsoleRef.current;
    if (!consoleNode) {
      return;
    }
    consoleNode.scrollTop = consoleNode.scrollHeight;
  }, [activityConsoleEntries.length]);

  const handleApproveAndContinue = useCallback(() => {
    setMockNotice({
      tone: 'success',
      title: 'Approval captured',
      detail: 'Nimbus resumed the session and moved into remediation on the same session page.',
    });
    setMockStateOverride('fixing');
  }, []);

  const handleKeepPaused = useCallback(() => {
    setMockNotice({
      tone: 'warning',
      title: 'Session still paused',
      detail: 'Nimbus will stay in the waiting state until you explicitly continue.',
    });
  }, []);

  const handleMockAdopt = useCallback(() => {
    setMockAdopted(true);
    setMockNotice({
      tone: 'success',
      title: 'Adoption complete',
      detail: 'Nimbus created an isolated local worktree for the reviewed result. You can inspect the local diff and merge back when you are satisfied.',
    });
  }, []);

  const handleMockMergeBack = useCallback(() => {
    setMockMergedBack(true);
    setMockNotice({
      tone: 'success',
      title: 'Merge back complete',
      detail: 'Nimbus merged the adopted worktree back into the current branch in this mock happy path.',
    });
  }, []);

  const motionProps = reduceMotion
    ? { initial: false as const }
    : {
        initial: { opacity: 0, y: 16 },
        animate: { opacity: 1, y: 0 },
        transition: { duration: 0.22, ease: 'easeOut' as const },
      };
  const hasReachedApprovalCheckpoint = !shouldReplayWaiting || visibleEvents.some((event) => event.kind === 'policy');
  const consoleSummary = shouldReplayWaiting && isWaitingReplayActive
    ? 'Replaying the lead-up to the approval checkpoint so you can see how the session arrives here.'
    : model.consoleSummary;
  const consoleBadgeLabel = shouldReplayWaiting
    ? isWaitingReplayActive
      ? 'replay'
      : 'snapshot'
    : model.canStream
      ? 'live tail'
      : 'snapshot';
  const findingsSummary = shouldReplayWaiting && isWaitingReplayActive
    ? 'Findings will populate here before Nimbus pauses for approval.'
    : model.findingsSummary;
  const checkpointEntryId = useMemo(
    () => findCheckpointConsoleEntryId(activityConsoleEntries, hasReachedApprovalCheckpoint),
    [activityConsoleEntries, hasReachedApprovalCheckpoint]
  );

