                <p>{model.terminal?.detail ?? model.result.summary}</p>
              </div>
              <div className="session-result-card">
                <span>Changed files</span>
                <strong>{model.result.changedFiles}</strong>
                <p>{model.result.changedFiles > 0 ? 'Nimbus produced a remediated result for local validation.' : 'Nimbus did not publish a remediated result for this session.'}</p>
              </div>
            </div>
          </motion.section>

          {model.result.reviewedDiff ? (
            <>
              <motion.section className="flow-section" {...motionProps}>
                <div className="section-header">
                  <div>
                    <p className="eyebrow">Reviewed diff</p>
                    <h2>What Nimbus changed</h2>
                  </div>
                </div>
                <div className="diff-card session-diff-card">
                  <div className="diff-meta">
                    {model.result.reviewedDiff.summary.map((item) => (
                      <span key={item}>{item}</span>
                    ))}
                  </div>
                  <pre>{model.result.reviewedDiff.patch}</pre>
                </div>
              </motion.section>

              <motion.section className="flow-section" {...motionProps}>
                <div className="section-header">
                  <div>
                    <p className="eyebrow">Adopt</p>
                    <h2>Bring the reviewed result local</h2>
                  </div>
                </div>
                {!mockAdopted ? (
                  <>
                    <p className="panel-body">{model.result.reviewedDiff.adoptDetail}</p>
                    <div className="button-row">
                      <button className="primary-button" onClick={handleMockAdopt}>
                        Adopt locally
                      </button>
                    </div>
                  </>
                ) : (
                  <div className="notice-card success">
                    <strong>Local worktree ready</strong>
                    <p>
                      Nimbus created an isolated worktree at <code>{model.result.reviewedDiff.worktreePath}</code>. Use the command below to enter it and test manually.
                    </p>
                    <pre>{model.result.reviewedDiff.enterCommand}</pre>
                  </div>
                )}
              </motion.section>

              {mockAdopted ? (
                <>
                  <motion.section className="flow-section" {...motionProps}>
                    <div className="section-header">
                      <div>
                        <p className="eyebrow">Local diff</p>
                        <h2>Changes in the adopted worktree</h2>
                      </div>
                    </div>
                    <div className="diff-card session-diff-card">
                      <div className="diff-meta">
                        <span>{`Branch: ${model.result.reviewedDiff.branchName}`}</span>
                        <span>{`Base: ${model.result.reviewedDiff.mergeTarget}`}</span>
                      </div>
                      <pre>{model.result.reviewedDiff.localDiff}</pre>
                    </div>
                  </motion.section>

                  <motion.section className="flow-section" {...motionProps}>
                    <div className="section-header">
                      <div>
                        <p className="eyebrow">Merge back</p>
                        <h2>Merge the adopted result into the current branch</h2>
                      </div>
                    </div>
                    <p className="panel-body">
                      Nimbus stays human-in-the-loop here too. Test the adopted worktree first, then merge back only when you are satisfied.
                    </p>
                    {!mockMergedBack ? (
                      <div className="button-row">
                        <button className="primary-button" onClick={handleMockMergeBack}>
                          Merge back into current branch
                        </button>
                      </div>
                    ) : (
                      <div className="notice-card success">
                        <strong>Merge back completed</strong>
                        <p>
                          Source branch <code>{model.result.reviewedDiff.sourceBranch}</code> was merged into <code>{model.result.reviewedDiff.mergeTarget}</code>.
                        </p>
                      </div>
                    )}
                  </motion.section>
                </>
              ) : null}
            </>
          ) : null}

          {model.result.noAdopt ? (
            <motion.section className="flow-section" {...motionProps}>
              <div className="section-header">
                <div>
                  <p className="eyebrow">Next step</p>
                  <h2>{model.result.noAdopt.title}</h2>
                </div>
              </div>
              <div className={`notice-card ${model.result.noAdopt.tone}`}>
                <strong>{model.result.noAdopt.title}</strong>
                <p>{model.result.noAdopt.detail}</p>
              </div>
            </motion.section>
          ) : null}
        </>
      ) : model.terminal ? (
        <motion.section className="panel-card session-terminal-card" {...motionProps}>
          <div className="section-header">
            <div>
              <p className="eyebrow">Session result</p>
              <h2>{model.terminal.title}</h2>
            </div>
          </div>
          <p className="panel-body">{model.terminal.detail}</p>
        </motion.section>
      ) : null}
    </main>
  );
}

function FindingList(props: {
  title: string;
  findings: ReviewFinding[];
  empty: string;
}): JSX.Element {
  return (
    <section className="flow-section">
      <div className="section-header">
        <div>
          <p className="eyebrow">Findings</p>
          <h2>{props.title}</h2>
        </div>
      </div>
      {props.findings.length === 0 ? (
        <div className="empty-card">{props.empty}</div>
      ) : (
        <div className="finding-list">
          {props.findings.map((finding, index) => (
            <motion.article
              key={`${findingHeading(finding)}-${findingLocation(finding) ?? index}`}
              className="finding-card"
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: Math.min(index * 0.03, 0.18) }}
            >
              <div className="finding-header">
                <span className={severityClass(finding.severity)}>{finding.severity}</span>
                {findingLocation(finding) ? <span className="finding-location">{findingLocation(finding)}</span> : null}
              </div>
              <strong>{findingHeading(finding)}</strong>
              {shouldShowFindingDescription(finding) ? <p>{finding.description}</p> : null}
              {finding.suggestedFix.trim() ? (
                <div className="finding-note">
                  <span>Suggested fix</span>
                  <p>{finding.suggestedFix}</p>
                </div>
              ) : null}
            </motion.article>
          ))}
        </div>
      )}
    </section>
  );
}

function ReviewSessionPageReal(props: { sessionId?: string }): JSX.Element {
  const { sessionId } = props;
  const reduceMotion = useReducedMotion();
  const streamRef = useRef<EventSource | null>(null);
  const activityConsoleRef = useRef<HTMLDivElement | null>(null);
  const [aggregate, setAggregate] = useState<StudioSessionAggregateResponse | null>(null);
  const [activity, setActivity] = useState<StudioSessionActivitySnapshot | null>(null);
  const [events, setEvents] = useState<StudioSessionActivityEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [policyDraft, setPolicyDraft] = useState<EditablePolicyDraft>(createEditablePolicyDraft(undefined));
  const [policyMessage, setPolicyMessage] = useState<string | null>(null);
  const [policyError, setPolicyError] = useState<string | null>(null);
  const [submittingPolicy, setSubmittingPolicy] = useState(false);
  const [adopting, setAdopting] = useState(false);
  const [adoptError, setAdoptError] = useState<string | null>(null);
  const [adoptResult, setAdoptResult] = useState<AdoptResponse | null>(null);
  const [localDiff, setLocalDiff] = useState<LocalReviewEnvironmentDiffResponse | null>(null);
  const [localDiffError, setLocalDiffError] = useState<string | null>(null);
  const [localDiffLoading, setLocalDiffLoading] = useState(false);
  const [mergeBackResult, setMergeBackResult] = useState<LocalReviewEnvironmentMergeBackResponse | null>(null);
  const [mergeBackError, setMergeBackError] = useState<string | null>(null);
  const [mergingBack, setMergingBack] = useState(false);

  const loadAggregate = useCallback(
    async (options?: { background?: boolean }) => {
      if (!sessionId) {
        setError('Session ID is missing from the route.');
        setLoading(false);
        return;
      }

      if (!options?.background) {
        setLoading(true);
      }
      setError(null);
      try {
        const nextAggregate = await fetchAggregate(sessionId);
        setAggregate(nextAggregate);
        setActivity(nextAggregate.activity);
      } catch (loadError) {
        setError(loadError instanceof Error ? loadError.message : String(loadError));
      } finally {
        setLoading(false);
      }
    },
    [sessionId]
  );

  useEffect(() => {
    setEvents([]);
    setAggregate(null);
    setActivity(null);
    setAdoptResult(null);
    setMergeBackResult(null);
    setLocalDiff(null);
    void loadAggregate();
    return () => {
      streamRef.current?.close();
      streamRef.current = null;
    };
  }, [loadAggregate]);

  useEffect(() => {
    if (!aggregate?.activeReview?.derivedPolicy) {
      return;
    }
    setPolicyDraft(createEditablePolicyDraft(aggregate.activeReview.derivedPolicy));
  }, [aggregate?.activeReview?.id, aggregate?.activeReview?.derivedPolicy]);

  const primaryEnvironment = aggregate?.local.environments[0] ?? null;

  const loadLocalDiff = useCallback(async (path: string) => {
    setLocalDiffLoading(true);
    setLocalDiffError(null);
    try {
      const response = await fetch(`${API_BASE}${path}`);
      const payload = await readJson(response);
      if (!response.ok) {
        throw new Error(readErrorMessage(payload));
      }
      setLocalDiff(parseLocalReviewEnvironmentDiffResponse(payload));
    } catch (diffError) {
      setLocalDiffError(diffError instanceof Error ? diffError.message : String(diffError));
    } finally {
      setLocalDiffLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!primaryEnvironment?.diffPath) {
      setLocalDiff(null);
      return;
    }
    void loadLocalDiff(primaryEnvironment.diffPath);
  }, [loadLocalDiff, primaryEnvironment?.diffPath]);

  useEffect(() => {
    if (!aggregate?.activity.canStream || isTerminalPhase(aggregate.session.phase)) {
      streamRef.current?.close();
      streamRef.current = null;
      return;
    }

    streamRef.current?.close();
    const source = new EventSource(`${API_BASE}${aggregate.paths.activityEvents}`);
    streamRef.current = source;

    const handleMessage = (messageEvent: MessageEvent<string>): void => {
      try {
        const event = parseStudioSessionActivityEvent(JSON.parse(messageEvent.data) as unknown);
        if (event.type === 'activity') {
          setEvents((current) => [...current, event].slice(-200));
          return;
        }
        if (event.type === 'snapshot' || event.type === 'terminal') {
          setActivity(event.activity);
          void loadAggregate({ background: true });
          return;
        }
        setError(event.message);
      } catch (streamError) {
        setError(streamError instanceof Error ? streamError.message : String(streamError));
      }
    };

    const handleTransportError = (): void => {
      source.close();
      if (!isTerminalPhase(aggregate.session.phase)) {
        setError('The live session stream disconnected. Refresh the page to reconnect.');
      }
    };

    source.addEventListener('message', handleMessage);
    source.addEventListener('error', handleTransportError);

    return () => {
      source.close();
      if (streamRef.current === source) {
        streamRef.current = null;
      }
    };
  }, [aggregate?.activity.canStream, aggregate?.paths.activityEvents, aggregate?.session.phase, loadAggregate]);

  const currentActivity = activity ?? aggregate?.activity ?? null;
  const contextMode = resolveContextMode(aggregate);
  const activeReview = aggregate?.activeReview ?? null;
  const isWaitingOnHuman = aggregate?.capabilities.waitingOnHuman === true;
  const isTerminal = aggregate?.capabilities.terminal === true;
  const canShowReviewedDiff = aggregate?.capabilities.canShowReviewedDiff === true && aggregate.reviewedDiff.available;
  const canAdopt = aggregate?.capabilities.canAdopt === true && aggregate.adopt.available;
  const unresolvedFindings = aggregate?.findings.unresolved ?? [];
  const resolvedFindings = useMemo(
    () => (aggregate?.findings.resolved ?? []).map((entry) => entry.finding),
    [aggregate?.findings.resolved]
  );
  const activityConsoleEntries = useMemo(() => {
    const liveEntries = events.map((event, index) => buildActivityConsoleEntry(event, index));
    const snapshotEntry = buildActivitySnapshotEntry(currentActivity);
    if (liveEntries.length === 0) {
      return [snapshotEntry];
    }
    if (isTerminal || isWaitingOnHuman) {
      const lastEntry = liveEntries[liveEntries.length - 1];
      if (lastEntry.line !== snapshotEntry.line || lastEntry.kind !== snapshotEntry.kind) {
        return [...liveEntries, snapshotEntry];
      }
    }
    return liveEntries;
  }, [currentActivity, events, isTerminal, isWaitingOnHuman]);
  const checkpointEntryId = useMemo(
    () => findCheckpointConsoleEntryId(activityConsoleEntries, isWaitingOnHuman),
    [activityConsoleEntries, isWaitingOnHuman]
  );

  useEffect(() => {
    const consoleNode = activityConsoleRef.current;
    if (!consoleNode) {
      return;
    }
    consoleNode.scrollTop = consoleNode.scrollHeight;
  }, [activityConsoleEntries.length, currentActivity?.updatedAt]);

  const motionProps = reduceMotion
    ? { initial: false as const }
    : {
        initial: { opacity: 0, y: 16 },
        animate: { opacity: 1, y: 0 },
        transition: { duration: 0.22, ease: 'easeOut' as const },
      };

  const handleApprovePolicy = useCallback(async () => {
    if (!activeReview) {
      return;
    }
    setSubmittingPolicy(true);
    setPolicyMessage(null);
    setPolicyError(null);
    try {
      const response = await fetch(`${API_BASE}/api/reviews/${encodeURIComponent(activeReview.id)}/policy/approve`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          approvedPolicy: normalizeEditablePolicyDraft(policyDraft),
        }),
      });
      const payload = await readJson(response);
      if (!response.ok) {
        throw new Error(readErrorMessage(payload));
      }
      setPolicyMessage('Policy approved. Nimbus will continue the session.');
      await loadAggregate({ background: true });
    } catch (approveError) {
      setPolicyError(approveError instanceof Error ? approveError.message : String(approveError));
    } finally {
      setSubmittingPolicy(false);
    }
  }, [activeReview, loadAggregate, policyDraft]);

  const handleAdopt = useCallback(async () => {
    if (!aggregate?.adopt.available) {
      return;
    }
    setAdopting(true);
    setAdoptError(null);
    setMergeBackResult(null);
    try {
      const response = await fetch(`${API_BASE}${aggregate.adopt.path}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ mode: 'worktree' }),
      });
      const payload = await readJson(response);
      if (!response.ok) {
        throw new Error(readErrorMessage(payload));
      }
      setAdoptResult(payload as AdoptResponse);
      await loadAggregate({ background: true });
    } catch (adoptFailure) {
      setAdoptError(adoptFailure instanceof Error ? adoptFailure.message : String(adoptFailure));
    } finally {
      setAdopting(false);
    }
  }, [aggregate?.adopt.available, aggregate?.adopt.path, loadAggregate]);

  const handleMergeBack = useCallback(async () => {
    if (!primaryEnvironment?.mergeBackPath) {
      return;
    }
    setMergingBack(true);
    setMergeBackError(null);
    try {
      const response = await fetch(`${API_BASE}${primaryEnvironment.mergeBackPath}`, {
        method: 'POST',
      });
      const payload = await readJson(response);
      if (!response.ok) {
        throw new Error(readErrorMessage(payload));
      }
      setMergeBackResult(parseLocalReviewEnvironmentMergeBackResponse(payload));
      await loadLocalDiff(primaryEnvironment.diffPath);
    } catch (mergeError) {
      setMergeBackError(mergeError instanceof Error ? mergeError.message : String(mergeError));
    } finally {
      setMergingBack(false);
    }
  }, [loadLocalDiff, primaryEnvironment?.diffPath, primaryEnvironment?.mergeBackPath]);

  if (loading && !aggregate) {
    return (
      <main className="studio-shell">
        <section className="panel-card">
          <p className="eyebrow">Loading</p>
          <h1>Loading review session…</h1>
        </section>
      </main>
    );
  }

  if (!aggregate || !currentActivity) {
    return (
      <main className="studio-shell">
        <section className="panel-card">
          <p className="eyebrow">Session</p>
          <h1>Review session unavailable</h1>
          <p className="panel-body">{error ?? 'Nimbus could not load the requested session.'}</p>
          <Link className="inline-link" to="/">
            Back to launch
          </Link>
        </section>
      </main>
    );
  }

  const stageTone = sessionTone({
    phase: aggregate.session.phase,
    terminal: isTerminal,
    waiting: isWaitingOnHuman,
  });
  const stageTitle = sessionStageTitle({
    phase: aggregate.session.phase,
    terminal: isTerminal,
    waiting: isWaitingOnHuman,
  });
  const repoBranchLabel = `${aggregate.session.repo} · ${aggregate.session.branch}`;
  const resultOutcomeLabel = aggregate.session.outcome?.kind.replace(/_/g, ' ') ?? currentActivity.summary;
  const resultSummary = aggregate.session.outcome?.summary ?? currentActivity.summary;
  const resultChangedFiles =
    aggregate.reviewedDiff.diff?.summary.totalChanged ??
    aggregate.session.outcome?.changes.changedFileCount ??
    0;
  const reviewedDiffFiles = aggregate.reviewedDiff.diff?.changedFiles ?? [];
  const reviewedDiffSummary = aggregate.reviewedDiff.diff
    ? [
        `${aggregate.reviewedDiff.diff.summary.totalChanged} file(s) changed`,
        aggregate.reviewedDiff.environmentRevision?.changedFileCount
          ? `${aggregate.reviewedDiff.environmentRevision.changedFileCount} file(s) in reviewed revision`
          : null,
        aggregate.reviewedDiff.diff.truncated ? 'Diff truncated for display' : null,
      ].filter((item): item is string => Boolean(item))
    : [];
  const noAdoptTitle = aggregate.session.phase === 'failed' ? 'No reviewed result' : 'No reviewed result to adopt';
  const noAdoptDetail =
    aggregate.reviewedDiff.reason ??
    (aggregate.session.phase === 'failed'
      ? 'Nimbus failed before it could publish a reviewed diff. Review the final console output and the unresolved findings before deciding whether to retry on a new commit.'
      : `Nimbus did not produce a remediated result for this session, so there is nothing to adopt locally.${
          unresolvedFindings.length > 0
            ? ' Address the remaining findings manually, commit that work, then start a new review on the new commit.'
            : ''
        }`);

  const activityHeading = isTerminal ? 'Final session output' : 'Live review console';
  const activitySubtle = currentActivity.canStream && !isTerminal
    ? 'New SSE events stream into this pane. Scroll stays inside the console, not the page.'
    : 'Recent session output for this browser session.';

  return (
    <main className="studio-shell session-shell">
      <motion.section className="panel-card session-stage-card" {...motionProps}>
        <div className="panel-header session-stage-header">
          <div>
            <p className="eyebrow">Review session</p>
            <h1 className="session-title">{stageTitle}</h1>
            <p className="launch-subline">{repoBranchLabel}</p>
          </div>
          <div className="session-stage-actions">
            <span className={`launch-status ${stageTone}`}>{sessionPhaseLabel(aggregate.session.phase)}</span>
            <Link className="inline-link" to="/">
              Back to launch
            </Link>
          </div>
        </div>
        <p className="panel-body">{currentActivity.detail}</p>
      </motion.section>

      {contextMode === 'basic' ? (
        <motion.section className="notice-card warning" {...motionProps}>
          <strong>Basic-mode session</strong>
          <p>Nimbus is reviewing the latest commit without Entire-backed intent context.</p>
          <a className="inline-link" href={ENTIRE_DOCS_URL} target="_blank" rel="noreferrer">
            Learn more about Entire
          </a>
        </motion.section>
      ) : null}

      {error ? (
        <section className="notice-card error">
          <strong>Live session error</strong>
          <p>{error}</p>
        </section>
      ) : null}

      {isWaitingOnHuman ? (
        <motion.section className="panel-card session-human-step-card" {...motionProps}>
          <div className="section-header">
            <div>
              <p className="eyebrow">Human step</p>
              <h2>{activeReview?.status === 'policy_ready' && activeReview.derivedPolicy ? 'Approve the review policy' : 'Nimbus is waiting on you'}</h2>
            </div>
          </div>
          <p className="panel-body">
            {activeReview?.status === 'policy_ready' && activeReview.derivedPolicy
              ? 'Nimbus paused before continuing remediation. Review the policy, edit it if needed, then approve it to resume the session. Nimbus will continue in an isolated review workspace, not your current checkout.'
              : 'Nimbus paused and is waiting for a human decision before it can continue.'}
          </p>
          {activeReview?.status === 'policy_ready' && activeReview.derivedPolicy ? (
            <>
              <div className="policy-grid">
                <label className="field-stack">
                  <span>Goal</span>
                  <textarea
                    value={policyDraft.goal}
                    onChange={(event) => setPolicyDraft((current) => ({ ...current, goal: event.target.value }))}
                    rows={3}
                  />
                </label>
                <label className="field-stack">
                  <span>Prohibitions</span>
                  <textarea
                    value={policyDraft.prohibitions}
                    onChange={(event) => setPolicyDraft((current) => ({ ...current, prohibitions: event.target.value }))}
                    rows={5}
                  />
                </label>
                <label className="field-stack">
                  <span>Constraints</span>
                  <textarea
                    value={policyDraft.constraints}
                    onChange={(event) => setPolicyDraft((current) => ({ ...current, constraints: event.target.value }))}
                    rows={5}
                  />
                </label>
              </div>
              <div className="button-row">
                <button className="primary-button" onClick={handleApprovePolicy} disabled={submittingPolicy}>
                  {submittingPolicy ? 'Approving policy…' : 'Approve policy'}
                </button>
              </div>
            </>
          ) : null}
          {policyMessage ? (
            <div className="notice-card success">
              <strong>Policy approved</strong>
              <p>{policyMessage}</p>
            </div>
          ) : null}
          {policyError ? (
            <div className="notice-card error">
              <strong>Approval failed</strong>
              <p>{policyError}</p>
            </div>
          ) : null}
        </motion.section>
      ) : null}

      {!isTerminal ? (
        <div className="session-live-grid">
          <motion.section className="flow-section session-console-section" {...motionProps}>
            <div className="section-header">
              <div>
                <p className="eyebrow">Session activity</p>
                <h2>{activityHeading}</h2>
              </div>
            </div>
            <div className="activity-console-card">
              <div className="activity-console-toolbar">
                <div>
                  <strong>Review stream</strong>
                  <p className="panel-subtle">{activitySubtle}</p>
                </div>
                <div className="activity-console-toolbar-meta">
                  <span>{aggregate.session.passCount} pass{aggregate.session.passCount === 1 ? '' : 'es'}</span>
                  <span>{modeLabel(contextMode)}</span>
                  <span className={`status-pill ${currentActivity.canStream && !isTerminal ? 'live' : 'muted'}`}>
                    {currentActivity.canStream && !isTerminal ? 'live tail' : 'snapshot'}
                  </span>
                </div>
              </div>
              <div className="activity-console-window" ref={activityConsoleRef} aria-live="polite">
                {activityConsoleEntries.map((entry) => (
                  <div
                    key={entry.id}
                    className={`activity-console-line ${entry.kind} ${entry.id === checkpointEntryId ? 'checkpoint' : ''}`}
                  >
                    <div className="activity-console-meta">
                      <span>{formatActivityConsoleTime(entry.createdAt)}</span>
                      {entry.passIndex !== null ? <span>{`pass ${entry.passIndex + 1}`}</span> : null}
                      <span>{activityConsoleKindLabel(entry.kind)}</span>
                      {entry.id === checkpointEntryId ? <span className="activity-console-tag">Pause point</span> : null}
                    </div>
                    <div className="activity-console-body">{entry.line}</div>
                  </div>
                ))}
              </div>
            </div>
          </motion.section>

          <motion.section className="flow-section session-findings-section" {...motionProps}>
            <div className="section-header">
              <div>
                <p className="eyebrow">Findings</p>
                <h2>What Nimbus has surfaced</h2>
              </div>
            </div>
            <p className="panel-subtle">
              {isWaitingOnHuman
                ? 'These findings remain open while the session waits for your decision.'
                : 'Findings appear here as Nimbus emits them.'}
            </p>
            <div className="session-findings-scroll">
              {unresolvedFindings.length === 0 ? (
                <div className="empty-card">No findings have materialized yet.</div>
              ) : (
                <div className="finding-list session-finding-list">
                  {unresolvedFindings.map((finding, index) => (
                    <motion.article
                      key={`${findingHeading(finding)}-${findingLocation(finding) ?? index}`}
                      className="finding-card"
                      initial={reduceMotion ? false : { opacity: 0, y: 10 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={reduceMotion ? undefined : { delay: Math.min(index * 0.05, 0.12), duration: 0.18 }}
                    >
                      <div className="finding-header">
                        <span className={severityClass(finding.severity)}>{finding.severity}</span>
                        {findingLocation(finding) ? <span className="finding-location">{findingLocation(finding)}</span> : null}
                      </div>
                      <strong>{findingHeading(finding)}</strong>
                      {shouldShowFindingDescription(finding) ? <p>{finding.description}</p> : null}
                    </motion.article>
                  ))}
                </div>
              )}
            </div>
          </motion.section>
        </div>
      ) : (
        <>
          <motion.section className="flow-section" {...motionProps}>
            <div className="section-header">
              <div>
                <p className="eyebrow">Outcome</p>
                <h2>Session result</h2>
              </div>
            </div>
            <div className="session-result-grid">
              <div className="session-result-card">
                <span>Outcome</span>
                <strong>{resultOutcomeLabel}</strong>
                <p>{resultSummary}</p>
              </div>
              <div className="session-result-card">
                <span>Recommendation</span>
                <strong>{recommendationLabel(aggregate, canShowReviewedDiff)}</strong>
                <p>{aggregate.session.outcome?.unresolved.findingCount ?? unresolvedFindings.length} unresolved finding(s) remain.</p>
              </div>
              <div className="session-result-card">
                <span>Changed files</span>
                <strong>{resultChangedFiles}</strong>
                <p>{aggregate.session.outcome?.changes.summaries[0] ?? 'Nimbus did not publish a remediation summary.'}</p>
              </div>
            </div>
          </motion.section>

          {canShowReviewedDiff && aggregate.reviewedDiff.diff ? (
            <motion.section className="flow-section" {...motionProps}>
              <div className="section-header">
                <div>
                  <p className="eyebrow">Reviewed diff</p>
                  <h2>What Nimbus changed</h2>
                </div>
              </div>
              <div className="diff-card session-diff-card">
                <div className="diff-meta">
                  {reviewedDiffSummary.map((item) => (
                    <span key={item}>{item}</span>
                  ))}
                </div>
                {reviewedDiffFiles.length > 0 ? (
                  <div className="session-file-list">
                    {reviewedDiffFiles.map((file) => (
                      <span key={`${file.status}-${file.path}`} className="session-file-chip">
                        {file.status}
                        {' '}
                        {file.path}
                      </span>
                    ))}
                  </div>
                ) : null}
                {aggregate.reviewedDiff.diff.patch?.trim() ? (
                  <pre>{aggregate.reviewedDiff.diff.patch}</pre>
                ) : (
                  <div className="empty-card">Nimbus has the changed-file summary, but not a patch body for this diff.</div>
                )}
              </div>
            </motion.section>
          ) : null}

          {primaryEnvironment || canAdopt ? (
            <motion.section className="flow-section" {...motionProps}>
              <div className="section-header">
                <div>
                  <p className="eyebrow">Adopt</p>
                  <h2>Bring the reviewed result local</h2>
                </div>
              </div>

              {!primaryEnvironment ? (
                <>
                  <p className="panel-body">
                    Adopting locally creates an isolated worktree for this reviewed result so you can run the code and test it yourself before merging anything back.
                  </p>
                  <div className="button-row">
                    <button className="primary-button" onClick={handleAdopt} disabled={!canAdopt || adopting}>
                      {adopting ? 'Adopting locally…' : 'Adopt locally'}
                    </button>
                  </div>
                  {aggregate.adopt.reason ? <p className="panel-subtle">{aggregate.adopt.reason}</p> : null}
                  {adoptError ? (
                    <div className="notice-card error">
                      <strong>Adoption failed</strong>
                      <p>{adoptError}</p>
                    </div>
                  ) : null}
                </>
              ) : (
                <div className="notice-card success">
                  <strong>Local worktree ready</strong>
                  <p>
                    Nimbus created an isolated worktree at <code>{primaryEnvironment.worktreePath ?? 'unknown path'}</code>.
                    Use the command below in your terminal to enter it and test manually.
                  </p>
                  <pre>{primaryEnvironment.enterCommand}</pre>
                </div>
              )}

              {adoptResult ? (
                <div className="notice-card success">
                  <strong>Adoption complete</strong>
                  <p>Local branch <code>{adoptResult.branchName}</code> is ready for manual validation.</p>
                  <pre>{adoptResult.enterCommand}</pre>
                </div>
              ) : null}
            </motion.section>
          ) : (
            <motion.section className="flow-section" {...motionProps}>
              <div className="section-header">
                <div>
                  <p className="eyebrow">Next step</p>
                  <h2>{noAdoptTitle}</h2>
                </div>
              </div>
              <div className={`notice-card ${aggregate.session.phase === 'failed' ? 'error' : 'warning'}`}>
                <strong>{noAdoptTitle}</strong>
                <p>{noAdoptDetail}</p>
              </div>
              {aggregate.adopt.reason ? <p className="panel-subtle">{aggregate.adopt.reason}</p> : null}
            </motion.section>
          )}

          {primaryEnvironment ? (
            <motion.section className="flow-section" {...motionProps}>
              <div className="section-header">
                <div>
                  <p className="eyebrow">Local diff</p>
                  <h2>Changes in the adopted worktree</h2>
                </div>
              </div>
              {localDiffLoading ? <div className="empty-card">Loading local diff…</div> : null}
              {!localDiffLoading && localDiffError ? (
                <div className="notice-card error">
                  <strong>Local diff failed</strong>
                  <p>{localDiffError}</p>
                </div>
              ) : null}
              {!localDiffLoading && !localDiffError && localDiff ? (
                localDiff.hasDiff ? (
                  <div className="diff-card session-diff-card">
                    <div className="diff-meta">
                      <span>Base ref: {localDiff.baseRef}</span>
                      <span>Branch: {localDiff.entry.branchName}</span>
                    </div>
                    <pre>{localDiff.diff}</pre>
                  </div>
                ) : (
                  <div className="empty-card">No local diff is present. Your adopted worktree matches the target base branch.</div>
                )
              ) : null}
            </motion.section>
          ) : null}

          {primaryEnvironment ? (
            <motion.section className="flow-section" {...motionProps}>
              <div className="section-header">
                <div>
                  <p className="eyebrow">Merge back</p>
                  <h2>Merge the adopted session into your current branch</h2>
                </div>
              </div>
              <p className="panel-body">
                Nimbus will only merge back when you ask it to. Keep your testing in the isolated worktree, then return here and merge when you are satisfied.
              </p>
              <div className="button-row">
                <button className="primary-button" onClick={handleMergeBack} disabled={mergingBack}>
                  {mergingBack ? 'Merging back…' : 'Merge back into current branch'}
                </button>
              </div>
              {mergeBackResult ? (
                <div className="notice-card success">
                  <strong>Merge back {mergeBackResult.status === 'already_applied' ? 'already applied' : 'completed'}</strong>
                  <p>
                    Source branch <code>{mergeBackResult.sourceBranch}</code> was merged into <code>{mergeBackResult.currentBranch}</code>.
                  </p>
                </div>
              ) : null}
              {mergeBackError ? (
                <div className="notice-card error">
                  <strong>Merge back failed</strong>
                  <p>{mergeBackError}</p>
                </div>
              ) : null}
            </motion.section>
          ) : null}

          <FindingList
            title="Still open"
            findings={unresolvedFindings}
            empty="Nimbus finished without unresolved findings."
          />

          <FindingList
            title="Resolved during this session"
            findings={resolvedFindings}
            empty="Nimbus did not resolve any previously emitted findings in this session."
          />

          <motion.section className="flow-section session-console-section" {...motionProps}>
            <div className="section-header">
              <div>
                <p className="eyebrow">Session activity</p>
                <h2>{activityHeading}</h2>
              </div>
            </div>
            <div className="activity-console-card">
              <div className="activity-console-toolbar">
                <div>
                  <strong>Review stream</strong>
                  <p className="panel-subtle">{activitySubtle}</p>
                </div>
                <div className="activity-console-toolbar-meta">
                  <span>{aggregate.session.passCount} pass{aggregate.session.passCount === 1 ? '' : 'es'}</span>
                  <span>{modeLabel(contextMode)}</span>
                  <span className="status-pill muted">snapshot</span>
                </div>
              </div>
              <div className="activity-console-window" ref={activityConsoleRef} aria-live="polite">
                {activityConsoleEntries.map((entry) => (
                  <div key={entry.id} className={`activity-console-line ${entry.kind}`}>
                    <div className="activity-console-meta">
                      <span>{formatActivityConsoleTime(entry.createdAt)}</span>
                      {entry.passIndex !== null ? <span>{`pass ${entry.passIndex + 1}`}</span> : null}
                      <span>{activityConsoleKindLabel(entry.kind)}</span>
                    </div>
                    <div className="activity-console-body">{entry.line}</div>
                  </div>
                ))}
              </div>
            </div>
          </motion.section>
        </>
      )}
    </main>
  );
}

