function statusFromReviewEventType(eventType: string): ReviewResponse['status'] | null {
  switch (eventType) {
    case 'review_created':
    case 'review_enqueued':
      return 'queued';
    case 'review_policy_derivation_started':
      return 'policy_pending';
    case 'review_policy_derivation_completed':
      return 'policy_ready';
    case 'review_succeeded':
      return 'succeeded';
    case 'review_failed':
      return 'failed';
    case 'review_cancelled':
