import { describe, expect, it } from 'vitest';
import { createMockStudioDataSource } from '../../data/studio/mockStudioDataSource';
import {
  parseStudioContextResponse,
  parseStudioNewReviewPreflightResponse,
  parseStudioSessionAggregateResponse,
} from '../../lib/review';

describe('studio parsers', () => {
  it('parses studio context response', () => {
    const payload = parseStudioContextResponse({
      repo: 'acme/web',
      branch: 'main',
      detectedAt: '2026-03-01T00:00:00.000Z',
    });

    expect(payload.repo).toBe('acme/web');
    expect(payload.branch).toBe('main');
  });

  it('parses new review preflight response', () => {
    const payload = parseStudioNewReviewPreflightResponse({
      repo: 'acme/web',
      branch: 'main',
      policyMode: 'auto',
      startability: 'intent_aware',
      contextMode: 'intent_aware',
      requestedLastCheckpoints: 1,
      effectiveLastCheckpoints: 1,
      lastCheckpoints: 1,
      checkpointSelectionMode: 'latest',
      checkpointId: 'cp_123',
      commitSha: 'abcdef1234567890',
      includedCheckpoints: [
        {
          checkpointId: 'cp_123',
          commitSha: 'abcdef1234567890',
          commitSubject: 'feat: latest checkpoint',
        },
      ],
      ready: true,
      capabilities: {
        canStart: true,
        canStartInBasicMode: true,
        canStartInIntentAwareMode: true,
        canReviewPolicy: true,
      },
      blockingIssues: [],
      warnings: [],
      checks: [
        {
          code: 'checkpoint',
          label: 'Checkpoint',
          ok: true,
          detail: 'Resolved checkpoint cp_123.',
        },
      ],
    });

    expect(payload.startability).toBe('intent_aware');
    expect(payload.checkpointId).toBe('cp_123');
    expect(payload.capabilities.canStart).toBe(true);
  });

  it('parses session aggregate responses for terminal studio sessions', async () => {
    const dataSource = createMockStudioDataSource({
      VITE_STUDIO_MOCK: '1',
      VITE_STUDIO_MOCK_SESSION_STATE: 'completed_diff',
    });

    const aggregate = await dataSource.loadSession('mock-completed_diff');
    const parsed = parseStudioSessionAggregateResponse(aggregate);

    expect(parsed.session.phase).toBe('completed');
    expect(parsed.reviewedDiff.available).toBe(true);
    expect(parsed.adopt.available).toBe(true);
  });
});

import { describe, expect, it } from 'vitest';
import { createMockStudioDataSource } from '../../data/studio/mockStudioDataSource';
import { buildSessionViewModel } from './sessionViewModel';

describe('buildSessionViewModel', () => {
  it('marks waiting sessions as editable human checkpoints', async () => {
    const dataSource = createMockStudioDataSource({
      VITE_STUDIO_MOCK: '1',
      VITE_STUDIO_MOCK_SESSION_STATE: 'waiting',
    });

    const aggregate = await dataSource.loadSession('mock-waiting');
    const viewModel = buildSessionViewModel({
      aggregate,
      activity: aggregate.activity,
      events: [],
      localDiff: null,
      adoptResult: null,
    });

    expect(viewModel.isWaitingOnHuman).toBe(true);
    expect(viewModel.policy.editable).toBe(true);
    expect(viewModel.stageTitle).toBe('Review paused');
  });

  it('surfaces adopt and reviewed diff state for completed sessions', async () => {
    const dataSource = createMockStudioDataSource({
      VITE_STUDIO_MOCK: '1',
      VITE_STUDIO_MOCK_SESSION_STATE: 'completed_diff',
    });

    const aggregate = await dataSource.loadSession('mock-completed_diff');
    const viewModel = buildSessionViewModel({
      aggregate,
      activity: aggregate.activity,
      events: [],
      localDiff: null,
      adoptResult: null,
    });

    expect(viewModel.isTerminal).toBe(true);
    expect(viewModel.reviewedDiff.visible).toBe(true);
    expect(viewModel.adopt.canAdopt).toBe(true);
    expect(viewModel.result?.recommendation).toBe('Adopt locally');
  });
});

import { act, cleanup, render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter } from 'react-router-dom';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { App } from '../../App';
import { StudioDataSourceProvider } from '../../data/studio/StudioDataSource';
import { createMockStudioDataSource } from '../../data/studio/mockStudioDataSource';
import { createStubStudioDataSource } from '../../test/studioDataSourceStub';

describe('StudioLaunchPage', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    cleanup();
  });

  it('starts a session from launch and routes into the shared session page', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
    const dataSource = createMockStudioDataSource({
      VITE_STUDIO_MOCK: '1',
      VITE_STUDIO_MOCK_SESSION_STATE: 'waiting',
    });

    render(
      <StudioDataSourceProvider value={dataSource}>
        <MemoryRouter initialEntries={['/']}>
          <App />
        </MemoryRouter>
      </StudioDataSourceProvider>
    );

    expect(await screen.findByRole('heading', { name: 'Review latest commit' })).toBeInTheDocument();

    await user.click(screen.getByRole('button', { name: 'Start review session' }));

    await act(async () => {
      vi.advanceTimersByTime(2_000);
    });

    expect(await screen.findByRole('heading', { name: 'Review paused' })).toBeInTheDocument();
    expect(screen.getByText('Approve the review policy')).toBeInTheDocument();
  });

  it('resumes the current session instead of showing a second launch path', async () => {
    const backingSource = createMockStudioDataSource({
      VITE_STUDIO_MOCK: '1',
      VITE_STUDIO_MOCK_SESSION_STATE: 'completed_diff',
    });
    const aggregate = await backingSource.loadSession('session_existing');
    const dataSource = createStubStudioDataSource({
      async loadLaunchState() {
        return {
          context: {
            repo: 'dayhaysoos/nimbus',
            branch: 'codex/studio-launch-rebuild',
            detectedAt: '2026-04-16T00:00:00.000Z',
          },
          preflight: {
            repo: 'dayhaysoos/nimbus',
            branch: 'codex/studio-launch-rebuild',
            policyMode: 'auto',
            startability: 'intent_aware',
            contextMode: 'intent_aware',
            requestedLastCheckpoints: 1,
            effectiveLastCheckpoints: 1,
            lastCheckpoints: 1,
            checkpointSelectionMode: 'latest',
            checkpointId: 'checkpoint_existing',
            commitSha: '4f8c2be',
            includedCheckpoints: [],
            ready: true,
            capabilities: {
              canStart: true,
              canStartInBasicMode: true,
              canStartInIntentAwareMode: true,
              canReviewPolicy: true,
            },
            blockingIssues: [],
            warnings: [],
            checks: [],
          },
          currentSession: {
            ...aggregate.session,
            id: 'session_existing',
          },
        };
      },
      async loadSession() {
        return {
          ...aggregate,
          session: {
            ...aggregate.session,
            id: 'session_existing',
          },
        };
      },
    });

    render(
      <StudioDataSourceProvider value={dataSource}>
        <MemoryRouter initialEntries={['/']}>
          <App />
        </MemoryRouter>
      </StudioDataSourceProvider>
    );

    expect(await screen.findByRole('heading', { name: 'Review complete' })).toBeInTheDocument();
    expect(screen.getByText('Reviewed diff available')).toBeInTheDocument();
  });
});

import { cleanup, render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter } from 'react-router-dom';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { App } from '../../App';
import { StudioDataSourceProvider } from '../../data/studio/StudioDataSource';
import { createMockStudioDataSource } from '../../data/studio/mockStudioDataSource';

describe('StudioSessionPage', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    cleanup();
  });

  it('keeps policy approval inside the shared session route', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
    const dataSource = createMockStudioDataSource({
      VITE_STUDIO_MOCK: '1',
      VITE_STUDIO_MOCK_SESSION_STATE: 'waiting',
    });

    render(
      <StudioDataSourceProvider value={dataSource}>
        <MemoryRouter initialEntries={['/sessions/mock-waiting']}>
          <App />
        </MemoryRouter>
      </StudioDataSourceProvider>
    );

    expect(await screen.findByRole('heading', { name: 'Review paused' })).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: 'Approve policy' }));

    await waitFor(() => {
      expect(screen.getByRole('heading', { name: 'Review complete' })).toBeInTheDocument();
    });
    expect(screen.getByRole('button', { name: 'Adopt locally' })).toBeInTheDocument();
  });

  it('shows adopt and merge-back on the same terminal session route', async () => {
    const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
    const dataSource = createMockStudioDataSource({
      VITE_STUDIO_MOCK: '1',
      VITE_STUDIO_MOCK_SESSION_STATE: 'completed_diff',
    });

    render(
      <StudioDataSourceProvider value={dataSource}>
        <MemoryRouter initialEntries={['/sessions/mock-completed_diff']}>
          <App />
        </MemoryRouter>
      </StudioDataSourceProvider>
    );

    expect(await screen.findByRole('heading', { name: 'Review complete' })).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: 'Adopt locally' }));

    await waitFor(() => {
      expect(screen.getByText('Local worktree ready')).toBeInTheDocument();
    });
    expect(screen.getByRole('button', { name: 'Merge back into current branch' })).toBeInTheDocument();
  });
});

import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createMockStudioDataSource } from './mockStudioDataSource';

describe('mockStudioDataSource', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  it('streams launch stages and completes into a session route', () => {
    const dataSource = createMockStudioDataSource({
      VITE_STUDIO_MOCK: '1',
      VITE_STUDIO_MOCK_SESSION_STATE: 'waiting',
    });
    const events: string[] = [];

    dataSource.startSession(
      {
        repo: 'dayhaysoos/nimbus',
        branch: 'codex/studio-launch-rebuild',
        lastCheckpoints: 1,
        policyMode: 'auto',
      },
      {
        onEvent(event) {
          events.push(event.type === 'stage' ? event.stage : event.routePath);
        },
        onError(error) {
          throw error;
        },
      }
    );

    vi.advanceTimersByTime(2_000);

    expect(events).toContain('checkpoint');
    expect(events).toContain('/sessions/mock-waiting');
  });

  it('moves waiting sessions onto the shared completed-diff path after approval', async () => {
    const dataSource = createMockStudioDataSource({
      VITE_STUDIO_MOCK: '1',
      VITE_STUDIO_MOCK_SESSION_STATE: 'waiting',
    });
    const waiting = await dataSource.loadSession('mock-waiting');
    expect(waiting.capabilities.waitingOnHuman).toBe(true);

    await dataSource.approvePolicy({
      reviewId: waiting.activeReview?.id ?? 'missing',
      approvedPolicy: {
        goal: 'Keep the shared session route readable.',
        prohibitions: [],
        constraints: [],
      },
    });

    const approved = await dataSource.loadSession('mock-waiting');
    expect(approved.session.phase).toBe('completed');
    expect(approved.reviewedDiff.available).toBe(true);
  });
});

